-- =====================================================================
-- Pet insurance analytics mart — SQLite DDL
-- ALL DATA IS SYNTHETIC (generated by src/generate.py).
-- Grain:
--   policies    one row per policy
--   claims      one row per claim   (claim -> policy many-to-one)
--   claim_notes one row per note    (note  -> claim  many-to-one, subset)
-- =====================================================================

DROP TABLE IF EXISTS claim_notes;
DROP TABLE IF EXISTS claims;
DROP TABLE IF EXISTS policies;

CREATE TABLE policies (
    policy_id                 TEXT PRIMARY KEY,
    brand                     TEXT NOT NULL,
    species                   TEXT NOT NULL,   -- dog | cat
    breed                     TEXT NOT NULL,
    breed_size                TEXT NOT NULL,   -- giant|large|medium|small
    age                       INTEGER NOT NULL,
    age_bin                   TEXT NOT NULL,
    state                     TEXT NOT NULL,
    region                    TEXT NOT NULL,
    density                   TEXT NOT NULL,   -- urban|suburban|rural
    territory                 TEXT NOT NULL,   -- region-density, e.g. West-urban
    effective_date            TEXT NOT NULL,   -- ISO date
    exposure_years            REAL NOT NULL,
    in_window_exposure_years  REAL NOT NULL,
    lam_annual                REAL NOT NULL,   -- true annual claim rate (synthetic truth)
    expected_claims           REAL NOT NULL,
    annual_premium            REAL NOT NULL,
    earned_premium            REAL NOT NULL
);

CREATE TABLE claims (
    claim_id      TEXT PRIMARY KEY,
    policy_id     TEXT NOT NULL REFERENCES policies(policy_id),
    claim_date    TEXT NOT NULL,               -- ISO date
    claim_year    INTEGER NOT NULL,
    claim_month   INTEGER NOT NULL,
    yearfrac      REAL NOT NULL,               -- years since 2019-01-01 (inflation clock)
    condition     TEXT NOT NULL,               -- one of 12 categories
    claim_cost    REAL NOT NULL,               -- paid loss (synthetic $)
    brand         TEXT NOT NULL,
    species       TEXT NOT NULL,
    breed         TEXT NOT NULL,
    breed_size    TEXT NOT NULL,
    age           INTEGER NOT NULL,
    age_bin       TEXT NOT NULL,
    state         TEXT NOT NULL,
    territory     TEXT NOT NULL,
    has_note      INTEGER NOT NULL             -- 1 if a claim note exists
);

CREATE TABLE claim_notes (
    note_id   TEXT PRIMARY KEY,
    claim_id  TEXT NOT NULL REFERENCES claims(claim_id),
    category  TEXT NOT NULL,                   -- one of 12 categories
    note_text TEXT NOT NULL
);

CREATE INDEX idx_claims_policy   ON claims(policy_id);
CREATE INDEX idx_claims_date     ON claims(claim_date);
CREATE INDEX idx_claims_cond     ON claims(condition);
CREATE INDEX idx_claims_brand    ON claims(brand);
CREATE INDEX idx_notes_claim     ON claim_notes(claim_id);
CREATE INDEX idx_policies_brand  ON policies(brand);
CREATE INDEX idx_policies_state  ON policies(state);
